"use client"

import {
  forwardRef,
  type MouseEvent,
  type ReactNode,
  type RefObject,
  useEffect,
  useRef,
  useState,
} from "react"
import { useEventCallback } from "../lib/hooks/use-event-callback"
import { cx } from "../lib/utils/cx"
import { Button, type ButtonProps } from "../button/button"
import { type CartItemInput, useCartActions } from "../cart/cart"
import { useFlyToCart } from "./fly-to-cart"

export type AddToCartButtonState = "idle" | "adding" | "added"

export interface AddToCartButtonLabels {
  add?: ReactNode
  adding?: ReactNode
  added?: ReactNode
  soldOut?: ReactNode
  /** Announced politely once the item is in the cart. */
  announcement?: string
}

export interface AddToCartButtonProps extends Omit<ButtonProps, "loading" | "asChild"> {
  /** Runs on click. While its promise is pending the button shows a spinner. */
  onAdd?: () => void | Promise<unknown>
  /** Added to the surrounding `CartProvider` once `onAdd` resolves. */
  item?: CartItemInput
  quantity?: number
  soldOut?: boolean
  /** How long the "Added" confirmation shows, in ms. */
  addedDuration?: number
  /** Fly this element (usually the product image) into the `[data-cart-target]` on success. */
  flyFrom?: RefObject<Element | null>
  /** Called when `onAdd` rejects. Without it the error is rethrown. */
  onError?: (error: unknown) => void
  labels?: AddToCartButtonLabels
  /** Hide the leading bag icon. */
  hideIcon?: boolean
}

const defaultLabels = {
  add: "Add to cart",
  adding: "Adding…",
  added: "Added",
  soldOut: "Sold out",
  announcement: "Added to cart",
} satisfies Required<AddToCartButtonLabels>

const BagIcon = () => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.9"
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true"
  >
    <path d="M5 8h14l-1.2 11.1a2 2 0 0 1-2 1.9H8.2a2 2 0 0 1-2-1.9L5 8Z" />
    <path d="M9 10V7a3 3 0 0 1 6 0v3" />
  </svg>
)

const CheckIcon = () => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2.4"
    aria-hidden="true"
  >
    <path
      className="kg-add-to-cart__check [stroke-dasharray:1] [stroke-dashoffset:1] transition-[stroke-dashoffset] delay-(--kg-duration-fast) duration-(--kg-duration-slower) ease-kg-out in-data-[state=added]:[stroke-dashoffset:0]"
      d="m5 12.5 4.5 4.5L19 7.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      pathLength={1}
    />
  </svg>
)

type Face = "idle" | "adding" | "added"

/* The face each state replaces: it leaves upward while the new one rises from below. */
const outgoing: Record<Face, Face> = { idle: "added", adding: "idle", added: "adding" }

const faceClass = (face: Face, state: Face) =>
  cx(
    "kg-add-to-cart__face relative inline-flex items-center justify-center gap-2 [grid-area:1/1]",
    "transition-[opacity,translate,scale] duration-(--kg-duration-base) ease-kg-out",
    face !== state && "scale-[0.92] opacity-0",
    face !== state && (outgoing[state] === face ? "-translate-y-[70%]" : "translate-y-[70%]"),
    face === "added" && "text-kg-success-fg",
  )

/**
 * A primary "Add to cart" that morphs idle → spinner → check → idle around an async `onAdd`.
 * Every label is stacked in one grid cell, so the button keeps its width through the morph.
 */
export const AddToCartButton = forwardRef<HTMLButtonElement, AddToCartButtonProps>(
  (
    {
      onAdd,
      item,
      quantity = 1,
      soldOut = false,
      addedDuration = 1800,
      flyFrom,
      onError,
      labels,
      hideIcon = false,
      size = "lg",
      disabled,
      className,
      onClick,
      children,
      ...props
    },
    ref,
  ) => {
    const text = { ...defaultLabels, ...labels }
    const [state, setState] = useState<AddToCartButtonState>("idle")
    const cart = useCartActions()
    const fly = useFlyToCart()
    const mounted = useRef(true)
    const reportError = useEventCallback(onError)

    useEffect(() => {
      mounted.current = true
      return () => {
        mounted.current = false
      }
    }, [])

    useEffect(() => {
      if (state !== "added") return
      const timer = setTimeout(() => setState("idle"), addedDuration)
      return () => clearTimeout(timer)
    }, [state, addedDuration])

    const handleClick = async (event: MouseEvent<HTMLButtonElement>) => {
      onClick?.(event)
      if (event.defaultPrevented || state !== "idle" || soldOut) return
      setState("adding")
      try {
        await onAdd?.()
      } catch (error) {
        if (mounted.current) setState("idle")
        if (onError) reportError(error)
        else throw error
        return
      }
      if (item && cart) cart.addItem(item, quantity)
      if (flyFrom?.current) void fly(flyFrom.current)
      if (mounted.current) setState("added")
    }

    const unavailable = soldOut || disabled
    const idleLabel = soldOut ? text.soldOut : (children ?? text.add)

    return (
      <>
        <Button
          ref={ref}
          size={size}
          className={cx("kg-add-to-cart overflow-hidden", className)}
          data-state={soldOut ? "sold-out" : state}
          disabled={unavailable}
          aria-busy={state === "adding" || undefined}
          onClick={(event) => void handleClick(event)}
          {...props}
        >
          <span
            className={cx(
              "kg-add-to-cart__fill pointer-events-none absolute inset-0 bg-kg-success transition-opacity duration-(--kg-duration-base) ease-kg-out",
              state === "added" && !soldOut ? "opacity-100" : "opacity-0",
            )}
            aria-hidden="true"
          />
          <span className="kg-add-to-cart__stack grid place-items-center">
            <span
              className={faceClass("idle", soldOut ? "idle" : state)}
              data-face="idle"
              aria-hidden={state !== "idle"}
            >
              {!hideIcon && !soldOut && <BagIcon />}
              {idleLabel}
            </span>
            <span
              className={faceClass("adding", soldOut ? "idle" : state)}
              data-face="adding"
              aria-hidden={state !== "adding"}
            >
              <span
                className={cx(
                  "kg-add-to-cart__spinner size-[1em] rounded-full border-2 border-current border-e-transparent",
                  state === "adding" &&
                    "animate-spin [animation-duration:0.7s] motion-reduce:[animation-duration:1.6s]",
                )}
                aria-hidden="true"
              />
              {text.adding}
            </span>
            <span
              className={faceClass("added", soldOut ? "idle" : state)}
              data-face="added"
              aria-hidden={state !== "added"}
            >
              <CheckIcon />
              {text.added}
            </span>
          </span>
        </Button>
        <span className="kg-visually-hidden" aria-live="polite">
          {state === "added" ? text.announcement : ""}
        </span>
      </>
    )
  },
)

AddToCartButton.displayName = "AddToCartButton"

"use client"

import { useCallback, useRef } from "react"
import { useIsomorphicLayoutEffect } from "../lib/hooks/use-isomorphic-layout-effect"
import { useReducedMotion } from "../lib/hooks/use-reduced-motion"

export interface FlyToCartOptions {
  /** Where to land. Defaults to the first visible `[data-cart-target]`. */
  target?: Element | null
  /** Flight time in ms. */
  duration?: number
  /** How high the arc rises above the straight line, in px. */
  arc?: number
}

export type FlyToCart = (
  from: Element | null,
  options?: FlyToCartOptions,
) => Promise<void>

const STEPS = 16

const findTarget = (): Element | null => {
  for (const node of document.querySelectorAll("[data-cart-target]")) {
    const rect = node.getBoundingClientRect()
    if (rect.width > 0 && rect.height > 0) return node
  }
  return null
}

/** Scale bounce on the cart icon, so the add registers even without a flight. */
export const bumpCartTarget = (target: Element | null): void => {
  target?.animate?.(
    [
      { scale: 1 },
      { scale: 1.22, offset: 0.35 },
      { scale: 0.94, offset: 0.7 },
      { scale: 1 },
    ],
    { duration: 480, easing: "ease-out" },
  )
}

const makeGhost = (from: Element, rect: DOMRect): HTMLElement => {
  const image = from instanceof HTMLImageElement ? from : from.querySelector("img")
  let ghost: HTMLElement
  if (image) {
    const img = document.createElement("img")
    img.src = image.currentSrc || image.src
    img.alt = ""
    img.style.objectFit = "cover"
    ghost = img
  } else {
    ghost = from.cloneNode(true) as HTMLElement
  }
  ghost.setAttribute("aria-hidden", "true")
  Object.assign(ghost.style, {
    position: "fixed",
    left: `${rect.left}px`,
    top: `${rect.top}px`,
    width: `${rect.width}px`,
    height: `${rect.height}px`,
    margin: "0",
    zIndex: "2147483000",
    pointerEvents: "none",
    boxShadow: "var(--kg-shadow-lg)",
    transformOrigin: "center",
    willChange: "transform, opacity",
  })
  return ghost
}

/**
 * Returns `fly(fromElement)`: clones the product image (or `fromElement` itself) and sends it
 * along an arc into the cart icon, then bumps the icon. Under reduced motion only the bump plays.
 */
export const useFlyToCart = (): FlyToCart => {
  const reduced = useReducedMotion()
  const latest = useRef(reduced)
  useIsomorphicLayoutEffect(() => {
    latest.current = reduced
  })

  return useCallback(async (from, options = {}) => {
    const target = options.target ?? findTarget()
    if (!target) return
    if (latest.current || !from || typeof document.body.animate !== "function") {
      bumpCartTarget(target)
      return
    }
    const start = from.getBoundingClientRect()
    const end = target.getBoundingClientRect()
    if (start.width === 0 || start.height === 0) {
      bumpCartTarget(target)
      return
    }

    const ghost = makeGhost(from, start)
    document.body.append(ghost)

    const dx = end.left + end.width / 2 - (start.left + start.width / 2)
    const dy = end.top + end.height / 2 - (start.top + start.height / 2)
    const endScale = Math.max(
      0.06,
      Math.min(end.width / start.width, end.height / start.height),
    )
    const arc = options.arc ?? Math.min(220, Math.max(80, Math.abs(dx) * 0.35))
    // Quadratic Bézier from the image to the icon with its control point above both.
    const cx = dx * 0.35
    const cy = Math.min(0, dy) - arc

    const keyframes: Keyframe[] = Array.from({ length: STEPS + 1 }, (_, step) => {
      const t = step / STEPS
      const u = 1 - t
      const x = 2 * u * t * cx + t * t * dx
      const y = 2 * u * t * cy + t * t * dy
      const scale = 1 + (endScale - 1) * t ** 1.4
      return {
        offset: t,
        transform: `translate(${x}px, ${y}px) scale(${scale})`,
        opacity: t > 0.85 ? 1 - (t - 0.85) / 0.15 : 1,
        borderRadius: `${12 + 40 * t}%`,
      }
    })

    try {
      await ghost.animate(keyframes, {
        duration: options.duration ?? 720,
        easing: "cubic-bezier(0.45, 0, 0.25, 1)",
        fill: "forwards",
      }).finished
    } catch {
      // Cancelled (e.g. the page navigated): still clean up below.
    } finally {
      ghost.remove()
    }
    bumpCartTarget(target)
  }, [])
}

export {
  AddToCartButton,
  type AddToCartButtonLabels,
  type AddToCartButtonProps,
  type AddToCartButtonState,
} from "./add-to-cart-button"
export {
  bumpCartTarget,
  type FlyToCart,
  type FlyToCartOptions,
  useFlyToCart,
} from "./fly-to-cart"
